parameters.jsCode:
// Flatten whatever the IMAP node hands us into the columns `messages` expects.
//
// The field names differ between the node's formats and between versions, so nothing
// here assumes a shape. Where a field is missing that we cannot work without, this
// throws and prints the keys that WERE present - which turns "everything is null in
// the database" into a message that tells you what to fix.
// PUT YOUR OWN MAILBOX HERE. It is only a label - it is what the dashboard shows in the
// Account column so you can tell two mailboxes apart. It does not connect to anything;
// the actual connection is the IMAP credential on the trigger node.
const ACCOUNT = 'your-mailbox@example.com';

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const pick = (...names) => {
    for (const n of names) {
      const v = j[n];
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return undefined;
  };

  const rawFrom = pick('from', 'From', 'sender');
  if (!rawFrom) {
    throw new Error(
      'No sender field on this email. Keys present: ' + Object.keys(j).join(', ') +
      ' - the IMAP node format may have changed.'
    );
  }

  // "Dana Whitfield <dana@example.com>", or a parsed object, or a bare address.
  let fromEmail = '', fromName = '';
  if (typeof rawFrom === 'string') {
    const m = rawFrom.match(/^\s*"?([^"<]*)"?\s*<([^>]+)>\s*$/);
    if (m) { fromName = m[1].trim(); fromEmail = m[2].trim(); }
    else { fromEmail = rawFrom.trim(); }
  } else if (rawFrom.value && rawFrom.value[0]) {
    fromEmail = rawFrom.value[0].address || '';
    fromName = rawFrom.value[0].name || '';
  } else if (rawFrom.text) {
    fromEmail = String(rawFrom.text).trim();
  }
  if (!fromEmail) fromEmail = String(rawFrom).slice(0, 200);

  const subject = String(pick('subject', 'Subject') || '(no subject)');
  const body = String(pick('textPlain', 'text', 'textHtml', 'html', 'body') || '');

  const rawDate = pick('date', 'Date', 'receivedDate');
  const parsed = rawDate ? new Date(rawDate) : null;
  const receivedAt = (parsed && !isNaN(parsed)) ? parsed.toISOString()
                                                : new Date().toISOString();

  // A null message_id defeats the UNIQUE constraint - Postgres allows many nulls, so
  // every re-run would insert the same mail again. Build a stable one instead.
  const messageId = String(
    pick('messageId', 'message-id', 'messageID', 'id') ||
    (fromEmail + '|' + subject + '|' + receivedAt)
  );

  out.push({ json: {
    account: ACCOUNT,
    message_id: messageId,
    from_email: fromEmail,
    from_name: fromName,
    subject: subject,
    // The classifier does not need the whole thread, and the dashboard shows a line.
    body_excerpt: body.replace(/\s+/g, ' ').trim().slice(0, 600),
    received_at: receivedAt
  }});
}

return out;

