={{ JSON.stringify({
  model: "anthropic/claude-haiku-4.5",
  temperature: 0,
  messages: [
    { role: "system", content: "You sort a small business's email. Reply with ONLY a JSON object and nothing else - no prose, no code fence.

{"category": "lead|client|invoice|other", "needs_reply": true|false, "reason": "six words at most"}

category:
  lead    - someone who is not yet a customer, asking about work or pricing
  client  - an existing customer, about work already underway
  invoice - a bill, statement, receipt or payment notice
  other   - anything else, including newsletters and automated notices

needs_reply is true ONLY when a person must actually respond. A thank-you with no question, an FYI, and an automated notice are all false." },
    { role: "user", content: "From: " + $json.from_name + " <" + $json.from_email + ">
Subject: " + $json.subject + "

" + $json.body_excerpt }
  ]
}) }}

parameters.jsCode:
// Turn the model's text into the three columns, and never guess.
//
// Models wrap JSON in code fences about a third of the time regardless of the
// instruction, so strip the fence before parsing rather than hoping.
//
// When the output cannot be parsed or the category is not one of the four, this does
// NOT quietly fall back to "other" - that would file an unreadable answer next to
// genuine ones and look identical in the dashboard. It files it as `unclassified`
// with the reason, which is visible, countable, and obviously wrong on sight.
const VALID = ['lead', 'client', 'invoice', 'other'];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message &&
             $json.choices[0].message.content) || '';

const stripped = String(raw)
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

// The normalised item, not the raw email - these are the columns `messages` wants.
const base = $('Normalise').item.json;

let category = 'unclassified';
let needsReply = false;
let reason = '';

try {
  const parsedOut = JSON.parse(stripped);
  const c = String(parsedOut.category || '').toLowerCase().trim();
  if (VALID.includes(c)) {
    category = c;
    needsReply = parsedOut.needs_reply === true || parsedOut.needs_reply === 'true';
    reason = String(parsedOut.reason || '').slice(0, 120);
  } else {
    reason = 'model returned category ' + JSON.stringify(parsedOut.category);
  }
} catch (e) {
  reason = 'unparseable classifier output: ' + stripped.slice(0, 80);
}

// This node runs once per item, so it returns ONE object. Returning an array here
// fails with "A 'json' property isn't an object" - which points at the json key and
// not at the array, and costs you a while.
return { json: Object.assign({}, base, {
  category: category,
  needs_reply: needsReply,
  reason: reason
}) };
